sys_ux_client_script.script:
/**
 * Updates sys_property `sam.integration` by moving integrations with `complex: true` to Walk.
 * Changes button text dynamically.
 *
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
async function handler({ api, event, helpers, imports }) {
  try {
    console.log("Incoming event payload:", event);

    // Retrieve current sys_property value
    let sysProperty = await api.getSysProperty('sam.integration'); 
    console.log("Current sys_property value:", sysProperty);

    // Parse JSON if necessary
    let integrationData = typeof sysProperty === "string" ? JSON.parse(sysProperty) : sysProperty;

    // Move integrations with `complex: true` to "Walk"
    let updatedIntegrations = integrationData.map(integration => {
      if (integration.complex === true) {
        return { ...integration, phase: "Walk" }; // Adding a `phase` field dynamically
      }
      return integration;
    });

    // Save the updated sys_property
    await api.setSysProperty('sam.integration', JSON.stringify(updatedIntegrations));
    console.log("Updated sys_property:", updatedIntegrations);

    // Change button text dynamically
    await api.setState('buttonText', "Continue in this phase");

  } catch (error) {
    console.error("Error updating sys_property:", error);
  }
}
